package com.madhukar.upisplitter.controller;
import com.madhukar.upisplitter.dto.*; import com.madhukar.upisplitter.repository.*; import com.madhukar.upisplitter.service.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class AdminController {private final UserService users;private final PaymentPlanRepository plans;private final PaymentTransactionRepository txns;private final AuditLogRepository logs;private final AnalyticsService analytics;public AdminController(UserService u,PaymentPlanRepository p,PaymentTransactionRepository t,AuditLogRepository l,AnalyticsService a){users=u;plans=p;txns=t;logs=l;analytics=a;}@GetMapping("/stats") public ApiDtos.ApiResponse<ApiDtos.AdminStats> stats(){return ApiResponseFactory.ok("Admin stats",analytics.admin());}@GetMapping("/users") public ApiDtos.ApiResponse<java.util.List<AdminUserView>> userList(){return ApiResponseFactory.ok("Users loaded",users.all().stream().map(u->new AdminUserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name(),u.getCreatedAt(),u.getUpdatedAt())).toList());}@GetMapping("/payment-plans") public ApiDtos.ApiResponse<java.util.List<com.madhukar.upisplitter.model.PaymentPlan>> planList(){return ApiResponseFactory.ok("Payment plans loaded",plans.findAll());}@GetMapping("/transactions") public ApiDtos.ApiResponse<java.util.List<com.madhukar.upisplitter.model.PaymentTransaction>> txList(){return ApiResponseFactory.ok("Transactions loaded",txns.findAll());}@GetMapping("/audit-logs") public ApiDtos.ApiResponse<java.util.List<com.madhukar.upisplitter.model.AuditLog>> logs(){return ApiResponseFactory.ok("Audit logs loaded",logs.findTop100ByOrderByTimestampDesc());}}
